from typing import List

def get_maximum_distance(location: List[int], k: int) -> int:
    loc = sorted(location)
    if k >= len(loc):
        return 0

    def clusters_needed(d: int) -> int:
        # 一个中心放在整数点上、半径 d，能盖住长度不超过 2d 的一段
        cnt, left = 1, loc[0]
        for x in loc:
            if x - left > 2 * d:
                cnt += 1
                left = x
        return cnt

    lo, hi = 0, (loc[-1] - loc[0] + 1) // 2
    while lo < hi:
        mid = (lo + hi) // 2
        if clusters_needed(mid) <= k:
            hi = mid
        else:
            lo = mid + 1
    return lo
